with flattened as (select id, plan, currency, tier_value from price_tiers lateral view explode(tier_limits) x as tier_value) select plan, currency, dense_rank() over w_part as tier_value_dense_rank, percent_rank() over (order by tier_value desc) as tier_value_percent_rank, stddev_samp(tier_value) over w_running as currency_stddev_samp_tier_value, cume_dist() over (order by tier_value desc nulls first) as tier_value_cume_dist, stddev_samp(tier_value) over w_running as currency_stddev_samp_tier_value_2 from flattened window w_part as (partition by plan, currency order by tier_value desc nulls last), w_running as (partition by currency)
